function plusOne(digits: number[]): number[] {
  // Идём от младшего разряда к старшему
  for (let i = digits.length - 1; i >= 0; i--) {
    if (digits[i] < 9) {
      // Переноса нет: увеличили цифру — и готово
      digits[i]++;
      return digits;
    }
    // 9 + 1 = 10: пишем 0, единица переносится в следующий разряд
    digits[i] = 0;
  }

  // Все цифры были девятками (999 → 000): нужен новый старший разряд
  return [1, ...digits];
}

// Время: O(n) в худшем случае (все девятки), обычно O(1)
// Память: O(1), кроме случая с новым разрядом — O(n)
